139: // enqueueCRD enqueues a CRD.
140: func (c *controller) enqueueCRD(obj interface{}) {
141: 	key, err := kcpcache.DeletionHandlingMetaClusterNamespaceKeyFunc(obj)
142: 	if err != nil {
143: 		runtime.HandleError(err)
144: 		return
145: 	}
146: 
147: 	logger := logging.WithQueueKey(logging.WithReconciler(klog.Background(), ControllerName), key)
148: 	logger.V(4).Info("queueing CRD")
149: 	c.queue.Add(key)
150: }
