152: func (c *controller) enqueueFromAPIBinding(obj interface{}) {
153: 	binding, ok := obj.(*apisv1alpha1.APIBinding)
154: 	if !ok {
155: 		return
156: 	}
157: 
158: 	logger := logging.WithObject(logging.WithReconciler(klog.Background(), ControllerName), binding)
159: 
160: 	for _, boundResource := range binding.Status.BoundResources {
161: 		key := kcpcache.ToClusterAwareKey(apibinding.ShadowWorkspaceName.String(), "", boundResource.Schema.UID)
162: 		logging.WithQueueKey(logger, key).V(2).Info("queueing CRD via APIBinding")
163: 		c.queue.Add(key)
164: 	}
165: }
