167: // Start starts the controller, which stops when ctx.Done() is closed.
168: func (c *controller) Start(ctx context.Context, numThreads int) {
169: 	defer runtime.HandleCrash()
170: 	defer c.queue.ShutDown()
171: 
172: 	logger := logging.WithReconciler(klog.FromContext(ctx), ControllerName)
173: 	ctx = klog.NewContext(ctx, logger)
174: 	logger.Info("Starting controller")
175: 	defer logger.Info("Shutting down controller")
176: 
177: 	for i := 0; i < numThreads; i++ {
178: 		go wait.UntilWithContext(ctx, c.startWorker, time.Second)
179: 	}
180: 
181: 	<-ctx.Done()
182: }
