189: func (c *controller) processNextWorkItem(ctx context.Context) bool {
190: 	// Wait until there is a new item in the working queue
191: 	k, quit := c.queue.Get()
192: 	if quit {
193: 		return false
194: 	}
195: 	key := k.(string)
196: 
197: 	logger := logging.WithQueueKey(klog.FromContext(ctx), key)
198: 	ctx = klog.NewContext(ctx, logger)
199: 	logger.V(4).Info("processing key")
200: 
201: 	// No matter what, tell the queue we're done with this key, to unblock
202: 	// other workers.
203: 	defer c.queue.Done(key)
204: 
205: 	if err := c.process(ctx, key); err != nil {
206: 		runtime.HandleError(fmt.Errorf("%q controller failed to sync %q, err: %w", ControllerName, key, err))
207: 		c.queue.AddRateLimited(key)
208: 		return true
209: 	}
210: 	c.queue.Forget(key)
211: 	return true
212: }
